dataTransform.transform:
[
  edges.node~>|$|(
    $id := id;
    $note := $components.CompletionForm.data.maintenanceChecklistResults.edges.node[maintenanceChecklistTaskId=$id].note;
    $type := type;
    $results := $components.CompletionForm.data.maintenanceChecklistResults.edges.node[maintenanceChecklistTaskId=$id];

    $result :=
      (
        $count($results) = 0 
        ? "Incomplete" 
        : (
          $result := $results[0];  /* Assuming the first result is the relevant one*/
          $v := $result.value;
          $u := $result.maintenanceItemUsage;
          $r := $result.result;
          $c := $result.completed;

          /* Set the text variable based on the type and completion status */
          $text :=
            $type = "Item"  
              ? (
                $c ? 
                 (
                   $r
                    ? "Passed " & ($u ? "Usage: " & $u : "")
                    : "Failed, " & ($u ? "Usage: " & $u : "")
                )
              :"Skipped"
              )
            : $type = "Measurement" 
              ? (
                  $c ?
                    ( $r
                      ? "Passed, Value: " & $v
                      : "Failed, Value: " & $v
                    )
              : "Skipped";
              /*              
              : $type = "Attribute" 
              ? (
                  $c ?
                    ( $r
                      ? "Passed"
                      : "Failed"
                    )
               : "Skipped"; 
              */
              )
              : $c ? ($r ? "Passed" : "Failed") : "Skipped";
        )
      );

    /* Return the final structure with min/max values, result, and note */
    {
      "minMaxItem": minValue.value & "/" & maxValue.value & " " & minValue.unit.code,
      "minMax": minValue.value & "/" & maxValue.value & " " & minValue.unit.code,
      "result": $result,
      "note": $note
    }
  )|
]

action.query:
query result ($where: MaintenanceChecklistResultWhereInput) {
  maintenanceChecklistResult(where: $where) {
    edges {
      node {
      id
      maintenanceItemUsage
      value
      completed
      result
      note
      maintenanceCompletionId
      }
    }
  }
}

query Query($where: MaintenanceCompletionWhereInput, $orderBy: [MaintenanceCompletionOrderByInput!], $first: Int, $after: String) {
  maintenanceCompletion(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
      }
    }
  }
}
